repository_identity() {
  local url="$1"
  case "$url" in
    http://*|https://*)
      url="${url#*://}"
      url="${url#*@}"
      ;;
    ssh://*)
      url="${url#ssh://}"
      url="${url#*@}"
      ;;
    *@*:*)
      url="${url#*@}"
      url="${url/:/\/}"
      ;;
  esac
  url="${url%/}"
  url="${url%.git}"
